-- ADCT, comentários didáticos, lote 13 (arts. 116 a 124, inclusive 116-A), só a partir do texto no banco. Já aplicado.
update legislacao set contexto = $c$Parcelamento de débitos previdenciários dos Municípios com o RGPS$c$, aplicacao_pratica = $a$Autoriza, excepcionalmente, o parcelamento em até trezentas prestações mensais dos débitos de contribuições previdenciárias dos Municípios, inclusive autarquias e fundações, com o Regime Geral de Previdência Social, vencidos até 31 de agosto de 2025, ainda que em execução fiscal, inclusive os de obrigações acessórias e os de parcelamentos anteriores não quitados. O § 1º exige dos Municípios com regime próprio o atendimento, até 1º de março de 2027, das condições do art. 115, I a IV, sob pena de suspensão. O § 2º reduz multas em 40%, juros de mora em 80%, encargos legais em 40% e honorários em 25%. O § 3º corrige as parcelas pelo IPCA, com juros reais de 0%, 1% ou 2% ao ano para quem quitar em dezoito meses ao menos 20%, 10% ou 5% da dívida, e de 4% ao ano para os demais. Os §§ 4º a 11 excluem débitos prescritos ou decaídos, atribuem os critérios à Receita Federal e à PGFN, excluem do parcelamento o inadimplente por três meses consecutivos ou seis alternados, com impedimento de transferências voluntárias e responsabilização do Prefeito, salvo variações inesperadas de receita ou despesa, limitam a parcela ao menor valor entre o saldo dividido e 1% da receita corrente líquida média e tratam do resíduo. O § 12 admite quitação antecipada por moeda, participações societárias, bens, créditos, cessão de dívida ativa e de compensações financeiras pela exploração de recursos naturais.$a$ where codigo='adct' and numero=116 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Parcelamento de débitos previdenciários de consórcios intermunicipais$c$, aplicacao_pratica = $a$Autoriza, excepcionalmente, o parcelamento em até trezentas prestações mensais dos débitos de contribuições previdenciárias dos consórcios públicos intermunicipais com o Regime Geral de Previdência Social, até 31 de agosto de 2025, ainda que em execução fiscal, inclusive os de obrigações acessórias e de parcelamentos anteriores não quitados. Pelo parágrafo único, aplicam-se os §§ 2º a 6º do art. 116 (reduções, atualização e juros, débitos prescritos, critérios e exclusão por inadimplência).$a$ where codigo='adct' and numero=116 and titulo='Art. 116-A' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Formalização dos parcelamentos e vinculação do FPM$c$, aplicacao_pratica = $a$Exige a formalização dos parcelamentos dos arts. 115, 116 e 116-A até 31 de agosto de 2026, condicionada à autorização de vinculação do Fundo de Participação dos Municípios ao pagamento das prestações, na ordem de preferência: garantias e débitos em favor da União (art. 167, § 4º) (I), contribuições parceladas devidas ao Regime Geral de Previdência Social (II) e contribuições parceladas devidas ao regime próprio (III).$a$ where codigo='adct' and numero=117 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Regulamentação da renda básica familiar$c$, aplicacao_pratica = $a$Determinou que os limites, condições, normas de acesso e demais requisitos do art. 6º, parágrafo único, e do art. 203, VI, da Constituição fossem fixados em lei e regulamento até 31 de dezembro de 2022, dispensando, só no exercício de 2022, as limitações legais à criação, expansão ou aperfeiçoamento de ação governamental com aumento de despesa.$a$ where codigo='adct' and numero=118 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Piso da educação na pandemia da Covid-19$c$, aplicacao_pratica = $a$Em razão da calamidade da pandemia da Covid-19, afasta a responsabilização administrativa, civil ou criminal dos Estados, do Distrito Federal, dos Municípios e de seus agentes pelo descumprimento do art. 212 da Constituição exclusivamente em 2020 e 2021. O parágrafo único exige que o ente complemente, até o exercício de 2023, a diferença entre o valor aplicado em manutenção e desenvolvimento do ensino e o mínimo constitucional daqueles exercícios.$a$ where codigo='adct' and numero=119 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Estado de emergência dos combustíveis em 2022$c$, aplicacao_pratica = $a$Reconhece, no ano de 2022, estado de emergência decorrente da elevação extraordinária e imprevisível dos preços do petróleo, combustíveis e derivados e de seus impactos sociais. O parágrafo único determina que as medidas de enfrentamento, nos limites de despesas previstos em norma constitucional única, sejam atendidas por crédito extraordinário, fora da meta de resultado primário da Lei nº 14.194/2021 e do limite do art. 107, I, e ressalvadas do art. 167, III (I), com abertura do crédito sem os requisitos do art. 167, § 3º (II), e com dispensa das limitações legais e de compensação para aumento de despesa e renúncia de receita (III). Norma de vigência limitada a 2022.$a$ where codigo='adct' and numero=120 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Encerramento de contas PIS-Pasep não reclamadas$c$, aplicacao_pratica = $a$Determina o encerramento das contas dos patrimônios acumulados do art. 239, § 2º, da Constituição não reclamados há mais de vinte anos, após sessenta dias do aviso no Diário Oficial da União, ressalvada a reivindicação de interessado legítimo nesse prazo. Pelo parágrafo único, os valores são tidos por abandonados (art. 1.275, III, do Código Civil) e apropriados pelo Tesouro Nacional para investimentos do art. 107, § 6º-B, fora dos limites do art. 107, podendo o interessado reclamar ressarcimento à União em até cinco anos do encerramento.$a$ where codigo='adct' and numero=121 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Execução de repasses da Covid-19 até 2023$c$, aplicacao_pratica = $a$Permite que os entes executem até 31 de dezembro de 2023 as transferências do Fundo Nacional de Saúde e do Fundo Nacional de Assistência Social feitas diretamente aos fundos estaduais, municipais e distritais para enfrentamento da pandemia da Covid-19. Norma de prazo já encerrado.$a$ where codigo='adct' and numero=122 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Prazo adicional das permissões lotéricas$c$, aplicacao_pratica = $a$Assegura prazo de vigência adicional a todos os termos de credenciamento, contratos, aditivos e demais ajustes de permissão lotérica em vigor na data de publicação do dispositivo, contado do término do instrumento vigente, independentemente da data de seu termo inicial.$a$ where codigo='adct' and numero=123 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Transição para os tributos dos arts. 156-A e 195, V$c$, aplicacao_pratica = $a$Determina que a transição para os tributos dos arts. 156-A e 195, V, da Constituição siga os critérios dos arts. 125 a 133 do ADCT. Pelo parágrafo único, a contribuição do art. 195, V, é instituída pela mesma lei complementar do art. 156-A.$a$ where codigo='adct' and numero=124 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
